#include <vector>
#include <algorithm>

class Solution {
public:
    long long maximumTotalSum(std::vector<int>& maximumHeight) {
        std::sort(maximumHeight.rbegin(), maximumHeight.rend());
        long long curr = 1e18;
        long long total = 0;
        for (int h : maximumHeight) {
            long long assigned = std::min(curr - 1, (long long)h);
            if (assigned <= 0) return -1;
            total += assigned;
            curr = assigned;
        }
        return total;
    }
};

import java.util.Arrays;

class Solution {
    public long maximumTotalSum(int[] maximumHeight) {
        Arrays.sort(maximumHeight);
        int n = maximumHeight.length;
        long curr = Long.MAX_VALUE;
        long total = 0;

        for (int i = n - 1; i >= 0; i--) {
            long assigned = Math.min(curr - 1, (long) maximumHeight[i]);
            if (assigned <= 0) return -1;
            total += assigned;
            curr = assigned;
        }
        return total;
    }
}

var maximumTotalSum = function(maximumHeight) {
    maximumHeight.sort((a, b) => b - a);
    let curr = Infinity;
    let total = 0;

    for (const h of maximumHeight) {
        const assigned = Math.min(curr - 1, h);
        if (assigned <= 0) return -1;
        total += assigned;
